CREATE DATABASE IF NOT EXISTS biblioteca_joao CHARACTER SET utf8mb4;
USE biblioteca_joao;
CREATE TABLE IF NOT EXISTS autores (id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(150) NOT NULL, nacionalidade VARCHAR(80)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS livros (id INT AUTO_INCREMENT PRIMARY KEY, titulo VARCHAR(200) NOT NULL, isbn VARCHAR(13) UNIQUE, ano_publicacao INT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS livros_autores (livro_id INT NOT NULL, autor_id INT NOT NULL, PRIMARY KEY(livro_id, autor_id), FOREIGN KEY(livro_id) REFERENCES livros(id), FOREIGN KEY(autor_id) REFERENCES autores(id)) ENGINE=InnoDB;
